import { createTheme } from '@mui/material/styles';
import { purple } from '@mui/material/colors';


const theme = createTheme ({
    palette: {
        primary: {
            main:purple[300], 
        },
        secondary: {
           main: '#70ad4c'
        },       
    },
    typography: {
        h3: {
            fontSize: '34px',
            fontFamily: 'Segoe UI',
            fontWeight: '600',
            color: 'green[400]',
        }
    }
});


export default theme;
